const utcDate=s=>{const [y,m,d]=s.split('-').map(Number);return Date.UTC(y,m-1,d)};
const validDate=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(parseDate(s))&&idate(parseDate(s))===s&&s>='2020-01-01'&&s<='2100-12-31';
const plusDays=(s,n)=>{const d=parseDate(s);d.setDate(d.getDate()+n);return idate(d)};
