$('#recipe-modal').addEventListener('click',e=>{if(e.target===$('#recipe-modal')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal()}});
