window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=sanitize(JSON.parse(e.newValue));render();toast('Datos actualizados desde otra pesta\u00f1a.')}catch(err){}}});
/* Original Version B extension; integrated inside app.js by build script. */
function baseEnhanced(){return {schema:2,stepGoal:8000,activity:{},weekPlans:{},sessions:{},defaultMode:'3',trainingDate:today(),activityDate:today(),exerciseFilter:'all',equipment:'all',favorites:[],shopView:'cards'}}
function sanitizeEnhanced(raw){
 const b=baseEnhanced();if(!raw||typeof raw!=='object')return b;
 if(Number.isFinite(+raw.stepGoal))b.stepGoal=Math.round(clamp(+raw.stepGoal,1000,30000));
 if(Object.hasOwn(X.plans,raw.defaultMode))b.defaultMode=raw.defaultMode;
 for(const key of ['trainingDate','activityDate'])if(validDate(raw[key]))b[key]=raw[key];
 if(b.activityDate>today())b.activityDate=today();
 if(['all','Pecho','Espalda','Hombros','Brazos','Piernas','Abdomen','favorites'].includes(raw.exerciseFilter))b.exerciseFilter=raw.exerciseFilter;
 b.favorites=Array.isArray(raw.favorites)?[...new Set(raw.favorites.filter(id=>Object.hasOwn(X.exercises,id)))]:[];
 if(['cards','list'].includes(raw.shopView))b.shopView=raw.shopView;
 if(raw.activity&&typeof raw.activity==='object')for(const[date,r]of Object.entries(raw.activity).slice(-4000)){if(!validDate(date)||date>today()||!r||typeof r!=='object')continue;const a={};for(const[k,max]of[['steps',100000],['walk',720]])if(r[k]!==null&&r[k]!==''&&r[k]!==undefined&&Number.isFinite(+r[k])&&+r[k]>=0&&+r[k]<=max)a[k]=Math.round(+r[k]);if(Object.keys(a).length)b.activity[date]=a}
 if(raw.weekPlans&&typeof raw.weekPlans==='object')for(const[date,a]of Object.entries(raw.weekPlans).slice(-600)){if(validDate(date)&&monday(date)===date&&Array.isArray(a)&&a.length===7)b.weekPlans[date]=a.map(id=>Object.hasOwn(X.routines,id)?id:null)}
 if(raw.sessions&&typeof raw.sessions==='object')for(const[date,r]of Object.entries(raw.sessions).slice(-2500)){if(!validDate(date)||!r||!Object.hasOwn(X.routines,r.rid)||!Array.isArray(r.items))continue;const seen=new Set();b.sessions[date]={rid:r.rid,items:r.items.slice(0,20).filter(e=>e&&Object.hasOwn(X.exercises,e.id)&&!seen.has(e.id)&&(seen.add(e.id),true)).map(e=>({id:e.id,sets:Math.round(clamp(Number(e.sets)||3,1,8)),reps:String(e.reps||X.exercises[e.id].reps).slice(0,20),kg:e.kg!==null&&e.kg!==''&&Number.isFinite(+e.kg)?clamp(+e.kg,0,500):null,done:!!e.done&&date<=today()}))}}
 return b;
}
function monday(date){return plusDays(date,-((parseDate(date).getDay()+6)%7))}
function planForWeek(date){const m=monday(date);if(state.enhanced.weekPlans[m])return state.enhanced.weekPlans[m];const a=[...X.plans[state.enhanced.defaultMode].days];if(state.enhanced.defaultMode==='legacy'&&state.settings.optionalSat)a[5]='lowerB';return a}
function routineForDate(date){return state.enhanced.sessions[date]?.rid||planForWeek(date)[(parseDate(date).getDay()+6)%7]||null}
function weekRoutineCount(date){const m=monday(date);return Array.from({length:7},(_,i)=>routineForDate(plusDays(m,i))).filter(Boolean).length}
function getSession(date){const rid=routineForDate(date);if(state.enhanced.sessions[date])return state.enhanced.sessions[date];return {rid,items:rid?X.routines[rid].items.map(x=>({...x,kg:x.id==='bench'?(x.reps==='5'?state.loads.A:state.loads.C):x.kg})):[]}}
function ensureSession(date){if(!state.enhanced.sessions[date]){const s=getSession(date);state.enhanced.sessions[date]={rid:s.rid||'custom',items:s.items}}return state.enhanced.sessions[date]}
function setRoutine(date,rid){const m=monday(date),p=[...planForWeek(date)];p[(parseDate(date).getDay()+6)%7]=rid;state.enhanced.weekPlans[m]=p;delete state.enhanced.sessions[date];syncMenuDate(date)}
function syncMenuDate(date){const i=Math.round((utcDate(date)-utcDate(state.settings.startDate))/DAY);if(i>=0&&i<state.settings.days&&state.menu[i])delete state.menu[i].gym}
function weekVolume(date){const m=monday(date),totals={Pecho:0,Espalda:0,Hombros:0,Brazos:0,Piernas:0,Abdomen:0};let bench=0;for(let i=0;i<7;i++){const s=getSession(plusDays(m,i));if(s.items.some(x=>x.id==='bench'))bench++;for(const e of s.items)totals[X.exercises[e.id].group]+=e.sets}return {totals,bench}}
function activityStats(end=today()){const ds=Array.from({length:7},(_,i)=>plusDays(end,i-6)),r=ds.map(date=>({date,...(state.enhanced.activity[date]||{})})),known=r.filter(x=>x.steps!==undefined);return {rows:r,n:known.length,avg:known.length?known.reduce((s,x)=>s+x.steps,0)/known.length:null,total:known.reduce((s,x)=>s+x.steps,0),walk:r.reduce((s,x)=>s+(x.walk||0),0)}}
function homeEnhancements(){const t=state.enhanced.activity[today()]||{},stats=activityStats(),rid=routineForDate(today());return `<section class="v2-home-strip mt24"><div class="v2-home-stat"><span class="v2-round-icon">${I('steps')}</span><div><span class="tiny muted">Pasos de hoy \u00b7 registro manual</span><strong class="mono">${t.steps!==undefined?fmt(t.steps):'Sin registrar'} <small>/ ${fmt(state.enhanced.stepGoal)}</small></strong></div><button class="btn btn-small" data-action="nav" data-page="activity">Registrar</button></div><div class="v2-home-stat"><span class="v2-round-icon">${I('dumbbell')}</span><div><span class="tiny muted">M\u00fasculo + fuerza \u00b7 ${weekRoutineCount(today())} d\u00edas esta semana</span><strong>${rid?X.routines[rid].title:'Hoy: descanso y paseo'}</strong></div><button class="btn btn-small" data-action="nav" data-page="training">Mi semana</button></div></section>`}
function activityPage(){
 const end=state.enhanced.activityDate,a=state.enhanced.activity[end]||{},s=activityStats(end),goal=state.enhanced.stepGoal,pct=a.steps===undefined?0:clamp(a.steps/goal,0,1),max=Math.max(goal,...s.rows.map(x=>x.steps||0));
 return head('Cada paso tambi\u00e9n cuenta.','Tu paseo con el perro, el movimiento del d\u00eda y una referencia flexible. Sin competir con tu recuperaci\u00f3n.',`<button class="btn no-print" data-v2="steps-csv">${I('download')}Exportar actividad</button>`)+`
 <div class="v2-activity-grid"><section class="v2-step-hero"><div class="eyebrow">Tu actividad \u00b7 ${dateLabel(end)}</div><div class="v2-step-ring" style="--progress:${pct*360}deg"><div><span>${I('steps')}</span><strong class="mono">${a.steps===undefined?'\u2014':fmt(a.steps)}</strong><small>${a.steps===undefined?'a\u00fan sin registro':'pasos totales'}</small></div></div><p class="small">Referencia editable: <strong>${fmt(goal)} pasos</strong><br>No es un m\u00ednimo obligatorio ni un objetivo para adelgazar por s\u00ed solo.</p></section>
 <section class="card"><div class="card-head"><h2>Registra, no adivines</h2><span class="badge badge-muted">Manual</span></div><form id="activity-form"><div class="grid2"><div class="field"><label for="activity-date">Fecha</label><input class="input" id="activity-date" name="date" type="date" value="${end}" max="${today()}" min="2020-01-01" required data-v2-change="activity-date"></div><div class="field"><label for="activity-steps">Pasos totales del d\u00eda</label><input class="input" id="activity-steps" name="steps" type="number" min="0" max="100000" step="1" placeholder="Ej.: 8200" value="${a.steps??''}"></div><div class="field"><label for="activity-walk">Paseo con el perro (minutos)</label><input class="input" id="activity-walk" name="walk" type="number" min="0" max="720" step="1" placeholder="Ej.: 60" value="${a.walk??''}"></div><div class="field"><label for="step-goal">Referencia diaria (pasos)</label><input class="input" id="step-goal" name="goal" type="number" min="1000" max="30000" step="100" value="${goal}" required></div></div><p class="tiny muted mt16">Copia el total del m\u00f3vil o reloj. Los pasos del paseo <strong>ya forman parte del total</strong>: no se suman otra vez. Vac\u00edo significa sin dato, no cero. Una hora de paseo no equivale a una cantidad fija de pasos.</p><div class="flex wrap mt16"><button class="btn btn-primary" type="submit">${I('save')}Guardar registro</button><button class="btn" type="button" data-v2="activity-today">Hoy</button>${state.enhanced.activity[end]?`<button class="btn btn-danger" type="button" data-v2="delete-activity" data-date="${end}">Eliminar registro</button>`:''}</div></form></section></div>
 <div class="grid3 mt24"><section class="card"><div class="tiny muted">Media de los \u00faltimos 7 d\u00edas hasta ${dateLabel(end)}</div><div class="v2-big mono">${s.avg===null?'\u2014':fmt(s.avg)} <small>pasos</small></div><p class="tiny muted">${s.n} de 7 d\u00edas registrados; no rellenamos los huecos.</p></section><section class="card"><div class="tiny muted">Pasos registrados en ese periodo</div><div class="v2-big mono">${fmt(s.total)}</div><p class="tiny muted">${s.n<7?'Total parcial: faltan d\u00edas.':'Periodo completo.'}</p></section><section class="card"><div class="tiny muted">Paseos anotados</div><div class="v2-big mono">${fmt(s.walk)} <small>min</small></div><p class="tiny muted">No se convierten en calor\u00edas ni se suman a los pasos.</p></section></div>
 <section class="card mt24"><div class="card-head"><h2>Tu semana en movimiento</h2><span class="tiny muted">7 d\u00edas \u00b7 hasta ${dateLabel(end)}</span></div><div class="v2-bars" role="img" aria-label="Gr\u00e1fico de pasos diarios; los valores aparecen debajo de cada barra">${s.rows.map(r=>`<div class="v2-bar-col"><span class="v2-bar-num mono">${r.steps===undefined?'\u2014':fmt(r.steps)}</span><div class="v2-bar-track"><i class="v2-goal-line" style="bottom:${goal/max*100}%" title="Referencia: ${goal}"></i><span class="v2-bar-fill ${r.steps===undefined?'unknown':''}" style="height:${r.steps===undefined?2:Math.max(2,r.steps/max*100)}%"></span></div><strong>${parseDate(r.date).toLocaleDateString('es-ES',{weekday:'short'})}</strong><small>${dateLabel(r.date)}</small></div>`).join('')}</div><p class="tiny muted mt12">La l\u00ednea punteada marca tu referencia actual. No es un umbral m\u00e9dico.</p></section>
 <div class="grid2 mt24"><section class="card"><h2>En tu caso, empieza por observar</h2><p class="small muted mt12">Trabajas sobre todo sentado y ya paseas al perro alrededor de una hora al d\u00eda. Registra una semana habitual antes de aumentar la actividad. Los 8.000 pasos son un punto de partida editable, no una cifra calculada para ti.</p><p class="small muted mt12">Si tu media es menor y te recuperas bien, prueba a a\u00f1adir 500\u20131.000 pasos diarios y revisa c\u00f3mo te encuentras. Es una propuesta pr\u00e1ctica, no una regla. En d\u00edas de pierna puedes mantener un paseo tranquilo.</p><p class="tiny muted mt16">La actividad cotidiana complementa la fuerza. <a href="${X.sources[1].url}" target="_blank" rel="noopener noreferrer">OMS \u2197</a></p></section><section class="card"><h2>No hacen falta 10.000 perfectos</h2><p class="small muted mt12">Las investigaciones asocian caminar m\u00e1s con beneficios para la salud, incluso sin alcanzar 10.000 pasos. No demuestran que una cifra concreta elimine la barriga. La alimentaci\u00f3n, la fuerza y la recuperaci\u00f3n siguen contando.</p><p class="small muted mt12">Esta web no estima calor\u00edas quemadas, no aumenta tu comida autom\u00e1ticamente por caminar y no se conecta a tu reloj. Evita usar los pasos para compensar comidas del fin de semana.</p><p class="tiny muted mt16"><a href="${X.sources[2].url}" target="_blank" rel="noopener noreferrer">Revisi\u00f3n de pasos \u00b7 Universidad de S\u00eddney (2025) \u2197</a></p></section></div>`;
}
