 <div class="v2-filter-row no-print">${[['all','Todos'],['Pecho','Pecho'],['Espalda','Espalda'],['Hombros','Hombros'],['Brazos','Brazos'],['Piernas','Piernas'],['Abdomen','Abdomen'],['favorites','Mis favoritos']].map(([id,label])=>`<button class="btn btn-small ${group===id?'btn-primary':''}" data-v2="filter-exercise" data-filter="${id}">${label}</button>`).join('')}</div>
