 if(equip==='highpulley')machine=path('M289 20V250M279 36H289','M289 20V250M279 36H289','#aab8a5',7)+circle([282,36],[282,36],7,'#d3dfca');
 if(equip==='lowpulley')machine=rect(95,202,82,10,'#83997f')+rect(126,212,9,38,'#a6b8a2')+path('M285 81V246','M285 81V246','#b3c2ad',7);
 if(equip==='lat')machine+=path('M49 247V14H272V247','M49 247V14H272V247','#c2cbb7',5)+path(`M160 14L160 ${a.wl[1]}`,`M160 14L160 ${b.wl[1]}`,'#81917d',2);
