 if(equip==='lat')gear+=path(`M${a.wl[0]-13} ${a.wl[1]}H${a.wr[0]+13}`,`M${b.wl[0]-13} ${b.wl[1]}H${b.wr[0]+13}`,'#43614a',7);
 const db=(pa,pb)=>path(`M${pa[0]-13} ${pa[1]}h26`,`M${pb[0]-13} ${pb[1]}h26`,'#6e866b',5)+path(`M${pa[0]-12} ${pa[1]-7}v14M${pa[0]+12} ${pa[1]-7}v14`,`M${pb[0]-12} ${pb[1]-7}v14M${pb[0]+12} ${pb[1]-7}v14`,'#4b6a4e',7);
 if(['incline','shoulder','lateral','curl','hammer','row_chest','row_one','incline_curl','preacher','kickback','dbbench','split_squat','lunges'].includes(id)){gear+=db(a.wl,b.wl)+(['row_one','preacher','kickback'].includes(id)?'':db(a.wr,b.wr))}
