 if(equip==='cablecurl'){machine=path('M270 43V251','M270 43V251','#adbaa5',7);gear+=path(`M270 247L${nums(a.wl)}`,`M270 247L${nums(b.wl)}`,'#81917d',2)+path(`M${a.wl[0]-8} ${a.wl[1]}L${a.wr[0]+8} ${a.wr[1]}`,`M${b.wl[0]-8} ${b.wl[1]}L${b.wr[0]+8} ${b.wr[1]}`,'#587452',6);}
